import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u13")
C = "A2-B1"

L(1, "Kunnen e willen", "Capacidade, possibilidade e vontade.",
  ["Conjugar kunnen e willen e usá-los com o infinitivo no fim"],
  vocab=[V("v-kun","kun / kan","(tu) podes|consegues","verb",note="jij kunt/kan — ambas corretas"), V("v-wil","wil","quero|queres|quer","verb",note="ik wil, jij wilt, hij wil"),
         V("v-zwemmen-kunnen","kunnen + infinitivo","conseguir/saber fazer","expression",note="Ik kan zwemmen. = Sei nadar."), V("v-willen-dat","willen dat","querer que","expression",note="Ik wil dat je komt.")],
  ex=[("Kun jij autorijden?","Sabes conduzir?"),("Ik kan morgen niet komen.","Amanhã não posso vir."),("Wat wil je drinken?","O que queres beber?"),("Ik wil dat je eerlijk bent.","Quero que sejas sincero.")],
  gram=[G("g-modaal-basis","Verbos modais: estrutura","O modal conjuga-se na **2.ª posição**; o outro verbo vai **no infinitivo, no fim**: *Ik **kan** morgen niet **komen**.* **kunnen**: ik kan, jij kunt/kan, hij kan, wij kunnen. **willen**: ik wil, jij wilt/wil, hij wil, wij willen. Com **inversão**, *jij* perde o -t: *Kun je…? Wil je…?*",
    [("Kunnen jullie mij helpen?","Podem ajudar-me?"),("Wil je mee?","Queres vir?")],
    "Em português o infinitivo segue o modal («posso vir»); em neerlandês vai para o fim da frase.")],
  review=["v-kunnen","v-willen"],
  cefr=C, exs=[
    MA([("ik kan","eu posso"),("jij kunt","tu podes"),("ik wil","eu quero"),("jij wilt","tu queres")], "Formas.", ["v-kun","v-wil"]),
    CJ("kunnen","jij","___ jij autorijden?", ["Kun","Kan"], "Inversão: kun/kan je.", ["v-kun"]),
    CJ("willen","hij","Hij ___ later kok worden.", ["wil"], "hij wil (sem -t).", ["v-wil"]),
    CJ("kunnen","wij","Wij ___ morgen niet.", ["kunnen"], "wij kunnen.", ["v-kunnen"]),
    WO("Amanhã não posso vir.", ["Ik","kan","morgen","niet","komen"], "Infinitivo no fim.", ["v-kunnen"], alt=["Morgen kan ik niet komen"]),
    FE(["Wilt","je","koffie?"], 0, "Wil", "Com inversão, jij perde o -t: Wil je koffie?", ["v-wil"]),
    MC("Qual é a ordem correta?", ["*Ik kan goed zwemmen.","Ik kan zwemmen goed.|O infinitivo vai para o fim: Ik kan goed zwemmen."], "O infinitivo vai para o fim: Ik kan goed zwemmen.", ["v-zwemmen-kunnen"]),
    TR("pt-nl","Quero que sejas sincero.", ["Ik wil dat je eerlijk bent","Ik wil dat jij eerlijk bent"], "willen dat + verbo no fim.", ["v-willen-dat"]),
    TR("nl-pt","Kunnen jullie mij helpen?", ["Podem ajudar-me","Vocês podem ajudar-me","Conseguem ajudar-me"], "kunnen.", ["v-kunnen"]),
    LI("Wat wil je vanavond eten?", ["Wat wil je vanavond eten","Wat wil jij vanavond eten"], "O que queres comer hoje à noite?", "wil + eten.", ["v-wil"]),
  ], diff=3, mins=6)

L(2, "Moeten", "Obrigação e necessidade.",
  ["Usar moeten para obrigações e conselhos fortes"],
  vocab=[V("v-moeten","moeten","ter de|dever","verb",note="ik moet, jij moet, wij moeten"), V("v-verplicht-zijn","het is verplicht","é obrigatório","expression"),
         V("v-echt-moeten","je moet echt…","tens mesmo de…","expression"), V("v-moest","moest","tinha de|tive de","verb",note="imperfectum: moest/moesten")],
  ex=[("Ik moet morgen vroeg opstaan.","Amanhã tenho de me levantar cedo."),("Je moet echt dat museum zien!","Tens mesmo de ver esse museu!"),("We moesten lang wachten.","Tivemos de esperar muito."),("Moet ik nu betalen?","Tenho de pagar agora?")],
  gram=[G("g-moeten","Moeten","**moeten** = ter de / dever. Presente: ik/jij/hij **moet**, wij/jullie/zij **moeten**. Passado: **moest / moesten**. Também serve para conselhos entusiastas: *Je moet die film zien!*",
    [("Moet je werken vandaag?","Tens de trabalhar hoje?")],
    "Atenção: «moeten» é obrigação; para «não ter de» usa-se «niet hoeven» (próxima lição).")],
  review=["v-kunnen","v-willen","v-betalen","v-opstaan"],
  cefr=C, exs=[
    MA([("moeten","ter de"),("het is verplicht","é obrigatório"),("je moet echt…","tens mesmo de…"),("moest","tinha de")], "Obrigação.", ["v-moeten","v-verplicht-zijn","v-echt-moeten","v-moest"]),
    CJ("moeten","ik","Ik ___ morgen vroeg opstaan.", ["moet"], "ik moet.", ["v-moeten"]),
    CJ("moeten","wij","We ___ gisteren lang wachten.", ["moesten"], "Passado plural: moesten.", ["v-moest"], tense="passado-simples"),
    TR("pt-nl","Tenho de pagar agora?", ["Moet ik nu betalen"], "Inversão.", ["v-moeten"]),
    TR("pt-nl","Tens mesmo de ver esse museu!", ["Je moet echt dat museum zien","Jij moet echt dat museum zien","Je moet dat museum echt zien"], "Conselho entusiasta.", ["v-echt-moeten"]),
    TR("nl-pt","We moesten lang wachten.", ["Tivemos de esperar muito","Tivemos de esperar muito tempo","Tínhamos de esperar muito"], "moesten.", ["v-moest"]),
    MC("Qual é a frase correta?", ["*Ik moet vandaag werken.","Ik moet werk vandaag.|Infinitivo no fim: Ik moet vandaag werken."], "Infinitivo no fim: Ik moet vandaag werken.", ["v-moeten"]),
    MC("«Je moet die film zien!» é…", ["*uma recomendação entusiasta","uma ordem da polícia|Não.","uma proibição|Não."], "Uso coloquial.", ["v-echt-moeten"]),
    LI("Een fietslicht is 's avonds verplicht.", ["Een fietslicht is 's avonds verplicht"], "À noite a luz da bicicleta é obrigatória.", "verplicht.", ["v-verplicht-zijn"]),
    FB("Wat ___ ik meenemen naar de afspraak?", ["moet"], "ik moet.", ["v-moeten"], choices=["moet","moeten","moest"], tr="O que tenho de levar para a consulta?"),
  ], diff=3, mins=6)

L(3, "Hoeven: não ter de", "Je hoeft niet te komen. Dat hoeft niet.",
  ["Negar a obrigação com niet hoeven te"],
  vocab=[V("v-hoeven","hoeven","precisar (só com negação)","verb",note="Je hoeft niet te komen."), V("v-dat-hoeft-niet","dat hoeft niet","não é preciso","expression"),
         V("v-alleen-maar","alleen maar","só|apenas","expression"), V("v-geen-hoeven","geen … hoeven","não precisar de (nome)","expression",note="Je hoeft geen jas mee te nemen.")],
  ex=[("Je hoeft niet te komen.","Não precisas de vir."),("Dat hoeft niet, hoor.","Não é preciso, a sério."),("Je hoeft alleen maar te tekenen.","Só tens de assinar."),("Je hoeft geen paraplu mee te nemen.","Não precisas de levar guarda-chuva.")],
  gram=[G("g-hoeven","Niet hoeven te","A negação de **moeten** é **niet hoeven te** + infinitivo: *Je **moet** komen* → *Je **hoeft niet te** komen.* (não *moet niet*, que significa «não deves»!). **hoeven** só aparece com negação ou com **alleen (maar)**: *Je hoeft alleen maar te tekenen.*",
    [("Je moet niet roken.","Não deves fumar. (proibição/conselho)"),("Je hoeft niet te roken.","Não tens de fumar. (sem obrigação)")],
    "É como a diferença entre «não deves» e «não precisas».")],
  review=["v-moeten","v-niet","v-geen"],
  cefr=C, exs=[
    MA([("hoeven","precisar"),("dat hoeft niet","não é preciso"),("alleen maar","só"),("geen … hoeven","não precisar de")], "Sem obrigação.", ["v-hoeven","v-dat-hoeft-niet","v-alleen-maar","v-geen-hoeven"]),
    TR("pt-nl","Não precisas de vir.", ["Je hoeft niet te komen","Jij hoeft niet te komen"], "niet hoeven te.", ["v-hoeven"]),
    TR("pt-nl","Só tens de assinar.", ["Je hoeft alleen maar te tekenen","Je hoeft alleen te tekenen","Je moet alleen tekenen"], "alleen maar.", ["v-alleen-maar"]),
    TR("nl-pt","Dat hoeft niet, hoor.", ["Não é preciso","Não é preciso, a sério","Não precisa, a sério"], "dat hoeft niet.", ["v-dat-hoeft-niet"]),
    MC("«Não tens de pagar» (é grátis):", ["*Je hoeft niet te betalen.","Je moet niet betalen.|Isso soa a «não deves pagar».","Je hoeft niet betalen.|Falta «te»."], "niet hoeven te.", ["v-hoeven"]),
    FE(["Je","hoeft","niet","komen."], 3, "te komen", "hoeven pede «te»: Je hoeft niet te komen.", ["v-hoeven"]),
    FE(["Je","hoeft","morgen","te","werken."], 2, "morgen niet", "hoeven só se usa com negação: Je hoeft morgen niet te werken.", ["v-hoeven"]),
    WO("Não precisas de levar guarda-chuva.", ["Je","hoeft","geen","paraplu","mee","te","nemen"], "geen + mee te nemen.", ["v-geen-hoeven"]),
    LI("U hoeft niets mee te nemen.", ["U hoeft niets mee te nemen"], "Não precisa de trazer nada.", "niets hoeven.", ["v-hoeven"]),
    DL([("Gast","Zal ik mijn schoenen uitdoen?","Tiro os sapatos?"),("Gastvrouw","")], ["*Dat hoeft niet, hoor!","Je moet niet.|Soa a proibição.","Je hoeft.|Falta a negação."], "Não é preciso.", ["v-dat-hoeft-niet"]),
  ], diff=4, mins=7)

L(4, "Mogen e niet mogen", "Permissão e proibição.",
  ["Pedir e dar permissão e falar de proibições"],
  vocab=[V("v-mag","mag","posso (permissão)|é permitido","verb",note="ik/jij/hij mag, wij mogen"), V("v-niet-mogen","niet mogen","não poder (proibido)","expression"),
         V("v-mocht","mocht","podia (permissão)","verb",note="imperfectum: mocht/mochten")],
  ex=[("Mag ik hier parkeren?","Posso estacionar aqui?"),("Je mag hier niet roken.","Aqui não se pode fumar."),("Als kind mocht ik niet laat opblijven.","Em criança não me deixavam ficar acordado até tarde."),("Heeft u toestemming?","Tem autorização?")],
  gram=[G("g-mogen-kunnen","Mogen vs. kunnen","**mogen** = ter permissão: *Mag ik binnenkomen?* **kunnen** = ser possível/capaz: *Kan ik binnenkomen?* (a porta está aberta?). **niet mogen** = proibição: *Je mag hier niet fietsen.* Passado: **mocht / mochten**.",
    [("Mag ik iets vragen?","Posso fazer uma pergunta?"),("Hier mag je niet zwemmen.","Aqui não se pode nadar.")],
    "Em português «poder» serve para tudo; em neerlandês, permissão é «mogen».")],
  review=["v-toestemming","v-mogen","v-kunnen","v-roken","v-verboden"],
  cefr=C, exs=[
    MA([("mag","posso (permissão)"),("niet mogen","ser proibido"),("toestemming","autorização"),("mocht","podia")], "Permissão.", ["v-mag","v-niet-mogen","v-toestemming","v-mocht"]),
    TR("pt-nl","Posso estacionar aqui?", ["Mag ik hier parkeren"], "Permissão → mogen.", ["v-mag"]),
    TR("pt-nl","Aqui não se pode fumar.", ["Je mag hier niet roken","Hier mag je niet roken","U mag hier niet roken"], "niet mogen.", ["v-niet-mogen"]),
    TR("nl-pt","Als kind mocht ik niet laat opblijven.", ["Em criança não me deixavam ficar acordado até tarde","Quando era criança não podia ficar acordado até tarde"], "mocht.", ["v-mocht"]),
    MC("Pede autorização ao professor para sair:", ["*Mag ik even naar het toilet?","Kan ik naar het toilet?|Possível, mas «mag» é o pedido de permissão.","Moet ik naar het toilet?|Não."], "mogen.", ["v-mag"]),
    CJ("mogen","wij","Als kind ___ we niet alleen naar buiten.", ["mochten"], "Passado plural: mochten.", ["v-mocht"], tense="passado-simples"),
    AR("toestemming","a autorização","de", "-ing → de.", ["v-toestemming"]),
    FE(["Je","mag","hier","niet","te","roken."], 4, "roken", "Depois de mogen não se usa «te»: Je mag hier niet roken.", ["v-niet-mogen"]),
    LI("Hier mag je niet zwemmen.", ["Hier mag je niet zwemmen"], "Aqui não se pode nadar.", "niet mogen.", ["v-niet-mogen"]),
    FB("Je hebt ___ nodig van je werkgever.", ["toestemming"], "autorização.", ["v-toestemming"], choices=["toestemming","verboden","mag"], tr="Precisas de autorização do teu empregador."),
  ], diff=3, mins=6)

L(5, "Modais juntos e no perfectum", "Ik heb niet kunnen komen. Je had het moeten zeggen.",
  ["Combinar modais e reconhecê-los no perfectum"],
  vocab=[V("v-had-moeten","had moeten","devia ter (feito)","expression"), V("v-heb-kunnen","heb kunnen","pude|consegui","expression"),
         V("v-zou-moeten","zou moeten","devia","expression",note="Je zou meer moeten slapen."), V("v-spijt","spijt hebben","arrepender-se","expression")],
  ex=[("Ik heb gisteren niet kunnen komen.","Ontem não pude vir."),("Je had het moeten zeggen!","Devias ter dito!"),("Je zou meer moeten slapen.","Devias dormir mais."),("Ik heb er spijt van.","Arrependo-me disso.")],
  gram=[G("g-modaal-perfectum","Modal no perfectum","No perfectum, o modal fica no **infinitivo** (não em particípio) e vai junto do outro infinitivo, no fim: *Ik **heb** niet **kunnen komen**.* (não «gekund»). Conselho/arrependimento: **had … moeten** + infinitivo: *Je **had** het **moeten zeggen**.*",
    [("We hebben lang moeten wachten.","Tivemos de esperar muito."),("Ik had eerder moeten vertrekken.","Devia ter saído mais cedo.")],
    "Esta construção com dois infinitivos (o «duplo infinitivo») não existe em português.")],
  review=["v-moeten","v-kunnen","v-mag","v-zou"],
  cefr=C, exs=[
    MA([("had moeten","devia ter"),("heb kunnen","pude"),("zou moeten","devia"),("spijt hebben","arrepender-se")], "Modais compostos.", ["v-had-moeten","v-heb-kunnen","v-zou-moeten","v-spijt"]),
    WO("Ontem não pude vir.", ["Ik","heb","gisteren","niet","kunnen","komen"], "Dois infinitivos no fim.", ["v-heb-kunnen"]),
    WO("Devias ter dito!", ["Je","had","het","moeten","zeggen!"], "had … moeten + inf.", ["v-had-moeten"]),
    FE(["Ik","heb","niet","gekund","komen."], 3, "kunnen", "Com outro infinitivo, o modal fica no infinitivo: niet kunnen komen.", ["v-heb-kunnen"]),
    TR("pt-nl","Devias dormir mais.", ["Je zou meer moeten slapen","Jij zou meer moeten slapen"], "zou … moeten.", ["v-zou-moeten"]),
    TR("nl-pt","We hebben lang moeten wachten.", ["Tivemos de esperar muito","Tivemos de esperar muito tempo"], "Duplo infinitivo.", ["v-moeten"]),
    TR("pt-nl","Arrependo-me disso.", ["Ik heb er spijt van","Daar heb ik spijt van"], "spijt hebben van → er … van.", ["v-spijt"]),
    MC("«Ik had eerder moeten vertrekken» significa…", ["*Devia ter saído mais cedo.","Saí mais cedo.|Não saiu.","Tenho de sair mais cedo.|Não é presente."], "Arrependimento.", ["v-had-moeten"]),
    LI("Ik heb het niet kunnen vinden.", ["Ik heb het niet kunnen vinden"], "Não consegui encontrá-lo.", "heb … kunnen vinden.", ["v-heb-kunnen"]),
    SW("Escreva 2 frases: algo que não pôde fazer ontem e algo que devia ter feito.", ["Ik heb gisteren niet kunnen sporten. Ik had eerder naar bed moeten gaan."], ["**heb … niet kunnen** + infinitivo", "**had … moeten** + infinitivo", "Dois infinitivos juntos no fim"], 12, "Duplo infinitivo.", ["v-had-moeten","v-heb-kunnen"]),
  ], diff=4, mins=7)

W()
